package com.android.messaging.util;
import android.content.Context;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;
public final class UiUtil {private UiUtil(){} public static int dp(Context c,float v){return Math.round(v*c.getResources().getDisplayMetrics().density);}public static int readable(int color){double l=(.299*Color.red(color)+.587*Color.green(color)+.114*Color.blue(color))/255d;return l>.62?Color.BLACK:Color.WHITE;}public static String appearance(Context c){int colors=0;for(java.util.Map.Entry<String,?> e:AppPrefs.p(c).getAll().entrySet())if(e.getKey().startsWith("color_")||e.getKey().equals("accent")||e.getKey().equals("incoming")||e.getKey().equals("outgoing"))colors+=e.hashCode();return colors+":"+AppPrefs.darkGrey(c)+":"+AppPrefs.isDark(c)+":"+AppPrefs.hideMms(c)+":"+java.util.Locale.getDefault()+":"+java.util.TimeZone.getDefault().getID()+":"+android.text.format.DateFormat.is24HourFormat(c);}public static GradientDrawable rounded(Context c,int color,float radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(c,radius));return d;}public static GradientDrawable circle(int color){GradientDrawable d=new GradientDrawable();d.setShape(GradientDrawable.OVAL);d.setColor(color);return d;}public static String hex(int c){return String.format("#%06X",0xffffff&c);} }
